import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"故障排查","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 全局快捷键没有反应","slug":"_1-全局快捷键没有反应","link":"#_1-全局快捷键没有反应","children":[]},{"level":2,"title":"2. 搜索结果未更新或过时","slug":"_2-搜索结果未更新或过时","link":"#_2-搜索结果未更新或过时","children":[]},{"level":2,"title":"3. 网络驱动器未自动刷新","slug":"_3-网络驱动器未自动刷新","link":"#_3-网络驱动器未自动刷新","children":[]},{"level":2,"title":"4. 某个文件或文件夹完全搜不到","slug":"_4-某个文件或文件夹完全搜不到","link":"#_4-某个文件或文件夹完全搜不到","children":[]},{"level":2,"title":"5. 内联窗口中中文输入法候选框未弹出","slug":"_5-内联窗口中中文输入法候选框未弹出","link":"#_5-内联窗口中中文输入法候选框未弹出","children":[]},{"level":2,"title":"6. 日志查看与提交 Issue","slug":"_6-日志查看与提交-issue","link":"#_6-日志查看与提交-issue","children":[]}],"relativePath":"zh-CN/user-guide/troubleshooting.md","filePath":"zh-CN/user-guide/troubleshooting.md","lastUpdated":1791112464000}`),a={name:`zh-CN/user-guide/troubleshooting.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to “故障排查”">​</a></h1><p>在使用 Lertaro 的过程中遇到问题？请按照以下步骤逐步排查常见故障原因。</p><h2 id="_1-全局快捷键没有反应" tabindex="-1">1. 全局快捷键没有反应 <a class="header-anchor" href="#_1-全局快捷键没有反应" aria-label="Permalink to “1. 全局快捷键没有反应”">​</a></h2><ul><li><strong>检查后台服务运行状态</strong>：进入<a href="./settings/service-status.html"><strong>设置 → 运行状态</strong></a>，确认后台索引服务处于“运行中”。虽然普通快捷键由 App 处理，但提权挂钩进程依赖后台服务拉起。</li><li><strong>管理员权限隔离（UIPI）</strong>：若当前前台活动窗口是以管理员身份运行的（例如以管理员打开的终端或任务管理器），Windows 系统的安全机制（UIPI）会阻止低权限进程向高权限窗口发送快捷键。Lertaro 会自动尝试提权快捷键监听进程；若仍无响应，请确保后台服务处于正常运行状态。</li><li><strong>检查进程黑名单</strong>：在<a href="./settings/hotkeys-page.html#_3-进程黑名单-process-blacklist"><strong>设置 → 快捷键</strong></a>中检查当前前台程序是否被列入了“进程黑名单”。处于黑名单中的程序在前台时，Lertaro 会主动放行按键不做拦截。</li><li><strong>全屏游戏/独占应用放行</strong>：当检测到前台有独占全屏应用程序（如 3D 游戏、全屏播放器）时，Lertaro 默认会自动放行快捷键以防干扰操作。如果你希望在全屏下依然能够呼出搜索框，请在<strong>设置 → 快捷键</strong>中勾选<strong>全屏应用聚焦时仍然响应</strong>。</li></ul><h2 id="_2-搜索结果未更新或过时" tabindex="-1">2. 搜索结果未更新或过时 <a class="header-anchor" href="#_2-搜索结果未更新或过时" aria-label="Permalink to “2. 搜索结果未更新或过时”">​</a></h2><ul><li><strong>本地 NTFS / ReFS 磁盘</strong>：Lertaro 通过读取底层 USN 变更日志实现近乎零延迟的毫秒级实时更新。</li><li><strong>FAT32 / exFAT 磁盘</strong>：通过系统文件变更事件持续监听。</li><li><strong>手动重建索引</strong>：若由于系统意外断电等原因导致索引不一致，请前往<a href="./settings/index-drives.html"><strong>设置 → 索引 → 本地驱动器</strong></a>，在对应的磁盘上点击<strong>重建索引</strong>即可重新生成干净的内存索引。</li></ul><h2 id="_3-网络驱动器未自动刷新" tabindex="-1">3. 网络驱动器未自动刷新 <a class="header-anchor" href="#_3-网络驱动器未自动刷新" aria-label="Permalink to “3. 网络驱动器未自动刷新”">​</a></h2><ul><li><strong>定时扫描机制</strong>：网络共享（SMB / NAS）没有本地 NTFS 卷的底层变更日志，因此依赖定时轮询机制。</li><li><strong>检查刷新模式</strong>：在<a href="./settings/index-drives.html#_2-网络驱动器-network-drives"><strong>设置 → 索引 → 网络驱动器</strong></a>中检查该驱动器的刷新模式是否被误设为了“手动”；若设为手动，必须点击“重建索引”或改为定时刷新。</li><li><strong>符号链接环路保护</strong>：对于 NAS 共享中可能存在的递归符号链接，Lertaro 内置了环路检测引擎，会自动跳过死循环目录。</li></ul><h2 id="_4-某个文件或文件夹完全搜不到" tabindex="-1">4. 某个文件或文件夹完全搜不到 <a class="header-anchor" href="#_4-某个文件或文件夹完全搜不到" aria-label="Permalink to “4. 某个文件或文件夹完全搜不到”">​</a></h2><ul><li><strong>检查排除规则</strong>：进入<a href="./settings/index-drives.html#_5-排除规则-exclusions"><strong>设置 → 索引 → 排除规则</strong></a>，确认目标文件路径是否被精确路径、Glob 通配符或正则表达式规则意外命中。</li><li><strong>检查磁盘启用状态</strong>：在<a href="./settings/index-drives.html"><strong>设置 → 索引 → 本地驱动器</strong></a>中确认该文件所在的物理驱动器或目录是否处于开启状态。</li></ul><h2 id="_5-内联窗口中中文输入法候选框未弹出" tabindex="-1">5. 内联窗口中中文输入法候选框未弹出 <a class="header-anchor" href="#_5-内联窗口中中文输入法候选框未弹出" aria-label="Permalink to “5. 内联窗口中中文输入法候选框未弹出”">​</a></h2><ul><li><strong>无焦点设计原理</strong>：<a href="./getting-started.html#_3-三种窗口形态">内嵌窗口</a>为了在关闭后把焦点归还给宿主软件，特意采用了无焦点设计。输入法候选框依赖 Windows 真实键盘焦点，因此在内联窗口中可能不显示候选浮窗。</li><li><strong>推荐解决方案</strong>： <ol><li><strong>直接打拼音</strong>：Lertaro 内置了拼音别名引擎，直接输入拼音字母即可跳跃命中中文文件名（详见<a href="./search-syntax.html#_7-多语言智能别名"><strong>搜索语法</strong></a>），无需调用输入法候选框。</li><li><strong>切换为快速窗口</strong>：按下双击 <code>Ctrl</code> 唤出拥有完整焦点的快速窗口，即可正常使用任何输入法。</li></ol></li></ul><h2 id="_6-日志查看与提交-issue" tabindex="-1">6. 日志查看与提交 Issue <a class="header-anchor" href="#_6-日志查看与提交-issue" aria-label="Permalink to “6. 日志查看与提交 Issue”">​</a></h2><p>若上述步骤均未能解决你的问题，请进入<a href="./settings/service-status.html"><strong>设置 → 运行状态</strong></a>查看详细的运行日志：</p><ul><li><strong>Service 日志</strong>：记录后台索引服务、USN 日志读取、网络盘扫描与 IPC 通信状态。</li><li><strong>App 日志</strong>：记录前台 UI 渲染、插件加载、快捷键响应与配置变动。</li><li><strong>Hook 日志</strong>：记录全局键盘钩子与鼠标导航手势的事件流。</li></ul><p>你可以在日志面板中使用搜索框过滤关键词，或按日志等级（Info / Warn / Error）快速定位异常堆栈，并在 GitHub 提交 Issue 时附上相关日志以便快速定位。</p>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};